/**
 * maker = post-only limits with gated taker fallback. taker = market/IOC on all 3 legs, gated by a fresh taker-priced pre-flight (actual taker fees + depth-walked slippage + safety buffer must leave net > floor). adaptive = choose per fire whichever path has the higher expected realized P&L (maker EV uses per-route historical fill probabilities).
 */
export type GraphExecuteRequestExecutionStyle = typeof GraphExecuteRequestExecutionStyle[keyof typeof GraphExecuteRequestExecutionStyle];


export const GraphExecuteRequestExecutionStyle = {
  taker: 'taker',
  maker: 'maker',
  adaptive: 'adaptive',
} as const;

export interface GraphExecuteRequest {
  krakenKey: string;
  krakenSecret: string;
  coinbaseKey?: string;
  coinbaseSecret?: string;
  /** Exact route description to execute; omitted = fresh top route */
  routeDescription?: string;
  tradeSizeUsd?: number;
  krakenFeesPct?: number;
  coinbaseFeesPct?: number;
  minProfitUsd?: number;
  isDryRun?: boolean;
  /** maker = post-only limits with gated taker fallback. taker = market/IOC on all 3 legs, gated by a fresh taker-priced pre-flight (actual taker fees + depth-walked slippage + safety buffer must leave net > floor). adaptive = choose per fire whichever path has the higher expected realized P&L (maker EV uses per-route historical fill probabilities). */
  executionStyle?: GraphExecuteRequestExecutionStyle;
  /** FORCE MODE — skip the fill-rate feedback gate, historical-shortfall penalty, and consecutive-failure blacklist entirely. Fresh pre-flight profit gates (net profit minus slippage buffer > minProfitUsd) still apply; this never authorizes a trade the live re-quote says is unprofitable. */
  forceMode?: boolean;
  /** Max leg-1 maker reprices (cancel + re-place at the freshest aggressive maker price, pre-flight re-run each time) before the route is abandoned so execution falls through to the next-best one. */
  maxReprices?: number;
  /** Per-leg maker fill window in ms (clamped 1000–30000 server-side). Lower = faster taker fallback; default derives from maxReprices. */
  makerTimeoutMs?: number;
  /** Partial-fill acceptance in percent (server clamps to 50–100; default 99.9). A leg filled to at least this fraction counts as complete — the cycle proceeds sized to the actual fill and any residual inventory is swept back to USD at market instead of the whole cycle unwinding. */
  partialFillTolerancePct?: number;
  /** Trader-directed — when the leg-1 maker order doesn't fill in its window, fire the taker fallback immediately WITHOUT the taker-priced profit-floor gate. A decayed edge will execute at the fresh taker price, possibly at a loss. Still requires a readable fresh order book. */
  alwaysTakerFallback?: boolean;
  /** Micro-check freshness threshold (ms, clamped 50–5000): the cached in-memory book snapshot used for the adaptive pre-fire decision must be at most this old, otherwise the fire is SKIPPED (stale data never executes blind). */
  maxQuoteAgeMs?: number;
}

